RED.liveSync = (function() {

    var active = false;
    var _isRemoteApply = false;
    var _changeCounter = 0;
    var _pendingChanges = {}; // changeId -> {changes, timestamp}
    var _status = 'disconnected'; // 'live', 'watching', 'pending', 'applying', 'error', 'disconnected'

    function init() {
        active = true;
        _status = 'live';

        // Subscribe to livesync messages from server
        RED.comms.subscribe("livesync/#", function(topic, data) {
            if (topic === "livesync/applied") {
                handleApplied(data);
            } else if (topic === "livesync/error") {
                handleError(data);
            } else if (topic === "livesync/proposal-pending") {
                handleProposalPending(data);
            } else if (topic === "livesync/proposal") {
                handleIncomingProposal(data);
            } else if (topic === "livesync/proposal-rejected") {
                handleProposalRejected(data);
            }
        });

        // Listen for comms connection state
        RED.events.on("comms:connected", function() {
            _status = 'live';
            RED.events.emit("livesync:status-changed", { status: _status });
        });
        RED.events.on("comms:disconnected", function() {
            _status = 'disconnected';
            RED.events.emit("livesync:status-changed", { status: _status });
        });

        RED.events.emit("livesync:status-changed", { status: _status });

        // Listen for baton state changes to update live/watching status
        RED.events.on("baton:state-changed", function(data) {
            if (!active) return;
            if (RED.multiplayer && RED.multiplayer.isLocalBatonHolder()) {
                _status = 'live';
            } else {
                _status = 'watching';
            }
            RED.events.emit("livesync:status-changed", { status: _status });
        });
    }

    function isActive() {
        return active;
    }

    function getStatus() {
        return _status;
    }

    /**
     * Translate a history event into change operations and send to server.
     * Called from RED.history.push() when live sync is active.
     * Both baton holders and non-holders can publish — the server decides
     * whether to apply directly or queue as a proposal.
     */
    function publishChange(ev) {
        if (_isRemoteApply) return; // Don't echo remote changes back

        var changes = historyEventToChanges(ev);
        if (changes.length === 0) return;

        var changeId = "chg_" + (++_changeCounter) + "_" + Date.now();

        _pendingChanges[changeId] = {
            changes: changes,
            timestamp: Date.now()
        };

        _status = 'applying';
        RED.events.emit("livesync:status-changed", { status: _status });

        RED.comms.send("livesync/change", {
            changeId: changeId,
            changes: changes
        });
    }

    /**
     * Translate a history event into an array of ChangeOperation objects.
     */
    function historyEventToChanges(ev) {
        var changes = [];

        switch(ev.t) {
            case 'add':
                // Nodes were added
                if (ev.nodes) {
                    ev.nodes.forEach(function(n) {
                        var node = typeof n === 'string' ? RED.nodes.node(n) : n;
                        if (node) {
                            var cleaned = cleanNodeForSync(node);
                            // Ensure wires reflect current links, not stale node.wires
                            cleaned.wires = getNodeWires(node);
                            changes.push({ op: 'add', node: cleaned });
                        }
                    });
                }
                if (ev.links) {
                    // Links represent wiring changes - extract rewire ops.
                    // Deduplicate by source node since multiple links may
                    // share the same source.
                    var rewiredAddSources = {};
                    ev.links.forEach(function(link) {
                        if (!rewiredAddSources[link.source.id]) {
                            rewiredAddSources[link.source.id] = true;
                            var sourceNode = RED.nodes.node(link.source.id);
                            if (sourceNode) {
                                changes.push({
                                    op: 'rewire',
                                    nodeId: sourceNode.id,
                                    wires: getNodeWires(sourceNode)
                                });
                            }
                        }
                    });
                }
                if (ev.workspaces) {
                    ev.workspaces.forEach(function(ws) {
                        changes.push({ op: 'add', node: { id: ws.id, type: 'tab', label: ws.label } });
                    });
                }
                if (ev.subflows) {
                    ev.subflows.forEach(function(sf) {
                        changes.push({ op: 'add', node: cleanNodeForSync(sf) });
                    });
                }
                break;

            case 'delete':
                if (ev.nodes) {
                    ev.nodes.forEach(function(n) {
                        var nodeId = typeof n === 'string' ? n : n.id;
                        if (nodeId) {
                            changes.push({ op: 'remove', nodeId: nodeId });
                        }
                    });
                }
                if (ev.workspaces) {
                    ev.workspaces.forEach(function(ws) {
                        changes.push({ op: 'remove', nodeId: ws.id });
                    });
                }
                if (ev.subflows) {
                    ev.subflows.forEach(function(sf) {
                        changes.push({ op: 'remove', nodeId: sf.id });
                    });
                }
                // Also handle link removals as rewire ops
                if (ev.links) {
                    var rewiredSources = {};
                    ev.links.forEach(function(link) {
                        if (!rewiredSources[link.source.id]) {
                            rewiredSources[link.source.id] = true;
                            var sourceNode = RED.nodes.node(link.source.id);
                            if (sourceNode) {
                                changes.push({
                                    op: 'rewire',
                                    nodeId: sourceNode.id,
                                    wires: getNodeWires(sourceNode)
                                });
                            }
                        }
                    });
                }
                break;

            case 'edit':
                if (ev.node && ev.node.id) {
                    var currentNode = RED.nodes.node(ev.node.id) ||
                                     RED.nodes.workspace(ev.node.id) ||
                                     RED.nodes.subflow(ev.node.id);
                    if (currentNode) {
                        changes.push({
                            op: 'update',
                            nodeId: ev.node.id,
                            node: cleanNodeForSync(currentNode)
                        });
                    }
                }
                break;

            case 'move':
                if (ev.nodes) {
                    ev.nodes.forEach(function(nobj) {
                        var n = nobj.n || nobj;
                        changes.push({
                            op: 'update',
                            nodeId: n.id,
                            node: { id: n.id, x: n.x, y: n.y }
                        });
                    });
                }
                break;

            case 'replace':
                // Full replace events send the current state of affected nodes
                if (ev.config) {
                    // This is a complex operation, for now treat as a batch update
                    ev.config.forEach(function(n) {
                        changes.push({
                            op: 'update',
                            nodeId: n.id,
                            node: cleanNodeForSync(n)
                        });
                    });
                }
                break;

            case 'multi':
                // Multi wraps sub-events (e.g. function node edit with editState.history).
                // Recurse into each sub-event and collect all changes.
                if (ev.events && Array.isArray(ev.events)) {
                    ev.events.forEach(function(subEv) {
                        var subChanges = historyEventToChanges(subEv);
                        subChanges.forEach(function(c) { changes.push(c); });
                    });
                }
                break;

            case 'createSubflow':
                if (ev.subflow) {
                    changes.push({ op: 'add', node: cleanNodeForSync(ev.subflow.subflow) });
                    if (ev.subflow.nodes) {
                        ev.subflow.nodes.forEach(function(n) {
                            changes.push({ op: 'add', node: cleanNodeForSync(n) });
                        });
                    }
                }
                break;
        }

        return changes;
    }

    /**
     * Build the current wires array for a node from the live links.
     * node.wires is stale (only updated on export), so we derive it
     * from RED.nodes.getNodeLinks which reflects addLink/removeLink.
     */
    function getNodeWires(node) {
        var wires = [];
        var outputs = node.outputs || 0;
        for (var i = 0; i < outputs; i++) {
            wires.push([]);
        }
        var outLinks = RED.nodes.getNodeLinks(node, 0); // 0 = PORT_TYPE_OUTPUT
        if (outLinks) {
            outLinks.forEach(function(link) {
                if (link.sourcePort < wires.length) {
                    wires[link.sourcePort].push(link.target.id);
                }
            });
        }
        return wires;
    }

    /**
     * Clean a node for transmission - remove internal/editor-only properties.
     */
    function cleanNodeForSync(n) {
        if (!n || typeof n !== 'object') return null;
        var clean = {};
        for (var k in n) {
            if (n.hasOwnProperty(k) &&
                k[0] !== '_' &&
                k !== 'dirty' &&
                k !== 'changed' &&
                k !== 'selected' &&
                k !== 'valid' &&
                k !== 'validationErrors' &&
                typeof n[k] !== 'function') {
                clean[k] = n[k];
            }
        }
        return clean;
    }

    /**
     * Handle livesync/applied message from server.
     */
    function handleApplied(data) {
        // Clean up pending tracking
        if (data.changeId && _pendingChanges[data.changeId]) {
            delete _pendingChanges[data.changeId];
        }

        // Update revision
        if (data.rev) {
            RED.nodes.version(data.rev);
        }

        // Update status — non-holders go back to 'watching', holders to 'live'
        if (Object.keys(_pendingChanges).length === 0) {
            if (data.results && data.results.failed && data.results.failed.length > 0) {
                _status = 'error';
            } else if (RED.multiplayer && RED.multiplayer.isLocalBatonHolder()) {
                _status = 'live';
            } else {
                _status = 'watching';
            }
        }
        RED.events.emit("livesync:status-changed", { status: _status });

        // If this change came from another session, apply it locally
        var localMpSession = RED.multiplayer && RED.multiplayer.getSessionId
            ? RED.multiplayer.getSessionId()
            : null;
        var remoteMpSession = data.senderMpSession || null;

        if (remoteMpSession && remoteMpSession !== localMpSession) {
            applyRemoteChanges(data.changes, data.results);
        } else if (!remoteMpSession && data.session && data.session !== localMpSession) {
            // Fallback: compare comms session (for baton holder's own changes)
            applyRemoteChanges(data.changes, data.results);
        }

        // Emit node-level status for failed nodes
        if (data.results && data.results.failed) {
            data.results.failed.forEach(function(f) {
                RED.events.emit("livesync:node-error", { nodeId: f.nodeId, error: f.error });
            });
        }
    }

    /**
     * Handle livesync/error from server.
     */
    function handleError(data) {
        if (data.changeId && _pendingChanges[data.changeId]) {
            delete _pendingChanges[data.changeId];
        }
        _status = 'error';
        RED.events.emit("livesync:status-changed", { status: _status });
        RED.notify(RED._("livesync.error", { error: data.error || "Unknown error" }), "error");
    }

    /**
     * Handle livesync/proposal-pending — server ack that our change was
     * received as a proposal (we are not the baton holder).
     */
    function handleProposalPending(data) {
        if (data.changeId && _pendingChanges[data.changeId]) {
            _pendingChanges[data.changeId].proposalId = data.proposalId;
        }
        _status = 'pending';
        RED.events.emit("livesync:status-changed", { status: _status });
    }

    /**
     * Handle livesync/proposal — we are the baton holder and someone proposed
     * changes. Show a notification with Accept / Reject buttons.
     */
    function handleIncomingProposal(data) {
        var username = (data.user && data.user.username) || 'Someone';
        var count = data.changes ? data.changes.length : 0;
        var message = RED._("livesync.proposal.received", { user: username, count: count }) ||
            (username + ' proposed ' + count + ' change(s)');
        var notification;

        notification = RED.notify(message, {
            type: 'info',
            fixed: true,
            timeout: 30000,
            buttons: [
                {
                    text: RED._("livesync.proposal.accept") || "Accept",
                    class: "primary",
                    click: function() {
                        RED.comms.send("livesync/proposal-accept", {
                            proposalId: data.proposalId
                        });
                        notification.close();
                    }
                },
                {
                    text: RED._("livesync.proposal.reject") || "Reject",
                    click: function() {
                        RED.comms.send("livesync/proposal-reject", {
                            proposalId: data.proposalId
                        });
                        notification.close();
                    }
                }
            ]
        });
    }

    /**
     * Handle livesync/proposal-rejected — the baton holder rejected our proposal.
     */
    function handleProposalRejected(data) {
        if (data.changeId && _pendingChanges[data.changeId]) {
            delete _pendingChanges[data.changeId];
        }
        if (Object.keys(_pendingChanges).length === 0) {
            _status = 'watching';
        }
        RED.events.emit("livesync:status-changed", { status: _status });
        RED.notify(RED._("livesync.proposal.rejected") || "Your changes were not accepted", "warning");
    }

    /**
     * Apply changes from a remote session to the local editor model.
     */
    function applyRemoteChanges(changes, results) {
        if (!changes || !Array.isArray(changes)) return;

        _isRemoteApply = true;
        try {
            changes.forEach(function(change) {
                if (change.op === 'add' && change.node) {
                    applyRemoteAdd(change.node);
                } else if (change.op === 'remove' && change.nodeId) {
                    applyRemoteRemove(change.nodeId);
                } else if (change.op === 'update' && change.nodeId && change.node) {
                    applyRemoteUpdate(change.nodeId, change.node);
                } else if (change.op === 'rewire' && change.nodeId) {
                    applyRemoteRewire(change.nodeId, change.wires);
                }
            });
            RED.view.redraw(true);
        } finally {
            _isRemoteApply = false;
        }
    }

    function applyRemoteAdd(nodeData) {
        if (nodeData.type === 'tab') {
            RED.nodes.addWorkspace(nodeData);
            RED.workspaces.add(nodeData);
        } else if (nodeData.type === 'subflow') {
            RED.nodes.addSubflow(nodeData);
        } else {
            RED.nodes.add(nodeData);
            // Create links from the wires array so they render on canvas
            var node = RED.nodes.node(nodeData.id);
            if (node && nodeData.wires) {
                addLinksFromWires(node, nodeData.wires);
            }
        }
    }

    function applyRemoteRemove(nodeId) {
        var node = RED.nodes.node(nodeId);
        if (node) {
            RED.nodes.remove(nodeId);
            return;
        }
        var ws = RED.nodes.workspace(nodeId);
        if (ws) {
            RED.nodes.removeWorkspace(nodeId);
            RED.workspaces.remove(ws);
            return;
        }
        var sf = RED.nodes.subflow(nodeId);
        if (sf) {
            RED.nodes.removeSubflow(sf);
        }
    }

    function applyRemoteUpdate(nodeId, newProps) {
        var node = RED.nodes.node(nodeId) ||
                   RED.nodes.workspace(nodeId) ||
                   RED.nodes.subflow(nodeId);
        if (!node) return;

        var oldOutputs = node.outputs;
        for (var k in newProps) {
            if (newProps.hasOwnProperty(k) && k !== 'id') {
                node[k] = newProps[k];
            }
        }
        node.dirty = true;

        // If this is a regular node (not tab/subflow), trigger proper visual
        // refresh: resize label, handle output port count changes, etc.
        if (node.type && node.type !== 'tab' && node.type !== 'subflow') {
            node.resize = true;

            // If output count changed, update links accordingly
            if (oldOutputs !== undefined && node.outputs !== undefined &&
                node.outputs < oldOutputs) {
                // Outputs reduced — remove links from excess ports
                var outLinks = RED.nodes.getNodeLinks(node, 0);
                if (outLinks) {
                    outLinks.forEach(function(l) {
                        if (l.sourcePort >= node.outputs) {
                            RED.nodes.removeLink(l);
                        }
                    });
                }
            }
        }
    }

    /**
     * Create internal link objects from a node's wires array.
     * Used when adding a new node remotely so that wires render on canvas.
     */
    function addLinksFromWires(node, wires) {
        if (!wires || !Array.isArray(wires)) return;
        node.wires = wires;
        for (var port = 0; port < wires.length; port++) {
            if (!Array.isArray(wires[port])) continue;
            for (var j = 0; j < wires[port].length; j++) {
                var targetNode = RED.nodes.node(wires[port][j]);
                if (targetNode) {
                    RED.nodes.addLink({
                        source: node,
                        sourcePort: port,
                        target: targetNode
                    });
                }
            }
        }
    }

    function applyRemoteRewire(nodeId, wires) {
        var node = RED.nodes.node(nodeId);
        if (!node) return;
        node.wires = wires || [];

        // Remove existing outbound links for this node
        var oldLinks = RED.nodes.getNodeLinks(node, 0); // 0 = output
        if (oldLinks) {
            oldLinks.forEach(function(l) {
                RED.nodes.removeLink(l);
            });
        }

        // Create new links from the wires array
        for (var port = 0; port < node.wires.length; port++) {
            for (var j = 0; j < node.wires[port].length; j++) {
                var targetNode = RED.nodes.node(node.wires[port][j]);
                if (targetNode) {
                    RED.nodes.addLink({
                        source: node,
                        sourcePort: port,
                        target: targetNode
                    });
                }
            }
        }
        node.dirty = true;
    }

    return {
        init: init,
        isActive: isActive,
        getStatus: getStatus,
        publishChange: publishChange,
        historyEventToChanges: historyEventToChanges,
        applyRemoteChanges: applyRemoteChanges
    };

})();
